def test_positive_applicability_condition_requires_paired_cases():
    source = (
        "(1) Der Zuschlag beträgt 259 Euro, wenn die Person anspruchsberechtigt ist."
    )
    content = """\
format: rulespec/v1
module:
  source_verification:
    corpus_citation_path: de/statute/estg/32a
rules:
  - name: supplement_amount
    kind: parameter
    dtype: Money
    source: de/statute/estg/32a(1)
    versions: [{formula: 259}]
  - name: payable_supplement
    kind: derived
    dtype: Money
    source: de/statute/estg/32a(1)
    versions:
      - formula: 'if is_eligible: supplement_amount else: 0'
"""

    def case(is_eligible: bool) -> dict[str, object]:
        return {
            "name": f"eligible={is_eligible}",
            "input": {"is_eligible": is_eligible},
            "output": {"payable_supplement": 259 if is_eligible else 0},
        }

    positive_only = _analyze(content, source, test_cases=[case(True)])
    paired = _analyze(
        content,
        source,
        test_cases=[case(False), case(True)],
    )

    assert _has_issue(positive_only, "applicability", "paired")
    assert not any(
        "directional formula-toggle witnesses" in issue
        for issue in positive_only.issues
    )
    assert not paired.issues

    # A real evaluated pair can still fail to witness the source condition.
    # Feedback must distinguish this from absent pairs without accepting it.
    unrelated = _analyze(
        content.replace("is_eligible", "vehicle_is_blue"),
        source,
        test_cases=[
            {
                "name": f"blue={blue}",
                "input": {"vehicle_is_blue": blue},
                "output": {"payable_supplement": 259 if blue else 0},
            }
            for blue in (False, True)
        ],
    )
    assert _has_issue(unrelated, "applicability", "paired")
    assert _has_issue(
        unrelated,
        "recognized 2 directional formula-toggle witnesses",
        "1 distinct case pairs",
        "source-selector relevance",
    )


